    /// Adds an injected `file:` package (identified by its full lockfile key,
    /// e.g. `@repo/ui@file:packages/ui`) to the pruned `packages` and
    /// `snapshots` maps, recursively pulling in its transitive dependencies.
    fn add_injected_package(
        &self,
        key: &str,
        pruned_packages: &mut Packages,
        pruned_snapshots: &mut Snapshots,
    ) -> Result<(), crate::Error> {
        // Already included; this also guards against dependency cycles.
        if pruned_snapshots.contains_key(key) {
            return Ok(());
        }

        let Some(snapshot) = self
            .snapshots
            .as_ref()
            .and_then(|snapshots| snapshots.get(key))
        else {
            return Ok(());
        };
        pruned_snapshots.insert(key.to_string(), snapshot.clone());

        // The `packages` entry is keyed without any peer suffix.
        let dp = DepPath::parse(self.version(), key).map_err(Error::from)?;
        let package_key = self.format_key(dp.name, dp.version);
        if let Some(entry) = self.get_packages(&package_key) {
            pruned_packages.insert(package_key, entry.clone());
        }

        // Traverse the injected package's direct dependencies, pulling each one
        // (and, transitively, its own dependencies) into the pruned lockfile.
        for (name, version) in snapshot.dependencies() {
            let dependency_key = self.format_key(&name, &version);
            self.add_injected_package(&dependency_key, pruned_packages, pruned_snapshots)?;
        }

        Ok(())
    }
